COMPILED_SKIP = [re.compile(p) for p in ONET_SKIP_PATTERNS]


def should_skip(name: str) -> bool:
    name_stripped = name.strip()
    if len(name_stripped) < 2 or len(name_stripped) > 80:
        return True
    for pattern in COMPILED_SKIP:
        if pattern.search(name_stripped):
            return True
    return False


