ALIAS_MIN_WORDS = 2


def _is_too_generic(alias: str) -> bool:
    words = alias.strip().split()
    if len(words) < ALIAS_MIN_WORDS:
        return words[0] in GENERIC_ALIAS_WORDS
    return all(w in GENERIC_ALIAS_WORDS for w in words)


def _is_too_generic_custom_alias(alias: str) -> bool:
    words = alias.strip().split()
    if len(words) < ALIAS_MIN_WORDS:
        return words[0] in GENERIC_ALIAS_WORDS
    return False


def generate_aliases(name: str) -> list:
    aliases = set()
    lower = name.lower().strip()
    aliases.add(lower)

    no_punct = re.sub(r"[.\-/]", " ", lower)
    no_punct = re.sub(r"\s+", " ", no_punct).strip()
    if no_punct != lower:
        aliases.add(no_punct)

    no_space = lower.replace(" ", "")
    if no_space != lower and 3 < len(no_space) <= 20:
        aliases.add(no_space)

    apache_match = re.match(r"^apache\s+(.+)$", lower)
    if apache_match:
        short = apache_match.group(1)
        if len(short) > 3 and not _is_too_generic(short):
            aliases.add(short)

    amazon_match = re.match(r"^amazon\s+(.+)$", lower)
    if amazon_match:
        short = amazon_match.group(1)
        if len(short) > 3 and not _is_too_generic(short):
            aliases.add(short)

    ms_match = re.match(r"^microsoft\s+(.+)$", lower)
    if ms_match:
        short = ms_match.group(1)
        if len(short) > 3 and not _is_too_generic(short):
            aliases.add(short)

    normalized = unicodedata.normalize("NFKD", lower)
    normalized = "".join(c for c in normalized if not unicodedata.combining(c))
    if normalized != lower:
        aliases.add(normalized)

    aliases.discard(name)
    aliases.discard(lower)

    aliases = {a for a in aliases if not _is_too_generic(a)}

    return sorted(aliases)


# ─────────────────────────────────────────────────────────────
# DUPLICATE-KEY CHECK
# ─────────────────────────────────────────────────────────────
# Tracks brace depth to identify every top-level dict literal that
# feeds into MODERN_TECH_SKILLS -- the original literal itself, plus
# every BATCH_N_ADDITIONS block -- rather than assuming there's only
# one such block. A duplicate key hidden inside a BATCH_N_ADDITIONS
# block is exactly as much a silent overwrite (via .update()) as a
# duplicate inside the original literal, so every block is scanned the
# same way and keys are tracked ACROSS ALL of them combined.
#
# As of this revision there are no longer any intentional exceptions
# to carve out here: the only 5 skills that used to be re-declared
# across blocks (Microsoft Power Automate, Solution Design, Looker,
# Performance Optimization, MIS Reporting) now use _add_alias() instead
# of a second dict-key declaration, so every skill name appears as a
# literal dict key exactly once in this file. This checker can stay
# strict with no allowlist.
_DICT_BLOCK_START_RE = re.compile(r'^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*\{\s*$')
_KEY_LINE_RE = re.compile(r'^\s*"([^"]+)":\s*\(')


def _check_no_duplicate_keys(source_path: str) -> None:
    with open(source_path, "r", encoding="utf-8") as f:
        lines = f.readlines()

    seen = {}           # key -> (block_name, lineno) of first definition
    duplicates = {}      # key -> [(block_name, lineno), ...] of repeats

    block_name = None
    depth = 0

    for lineno, line in enumerate(lines, start=1):
        if depth == 0:
            m = _DICT_BLOCK_START_RE.match(line)
            if m and (m.group(1) == "MODERN_TECH_SKILLS" or m.group(1).endswith("_ADDITIONS")):
                block_name = m.group(1)
                depth = 1
            continue

        depth += line.count("{") - line.count("}")

        m = _KEY_LINE_RE.match(line)
        if m:
            key = m.group(1)
            if key in seen:
                duplicates.setdefault(key, [seen[key]]).append((block_name, lineno))
            else:
                seen[key] = (block_name, lineno)

        if depth <= 0:
            depth = 0
            block_name = None

    if duplicates:
        print("\n❌ DUPLICATE KEYS FOUND across MODERN_TECH_SKILLS / BATCH_*_ADDITIONS:")
        for key, locations in duplicates.items():
            where = ", ".join(f"{name}:{ln}" for name, ln in locations)
            print(f"   {key!r} defined at: {where}")
        raise ValueError(
            f"{len(duplicates)} duplicate skill name(s) found across "
            "MODERN_TECH_SKILLS and its BATCH_*_ADDITIONS blocks -- only "
            "the LAST definition of each survives silently via .update(). "
            "Merge or rename them before building the taxonomy, or use "
            "_add_alias() to append a single alias to an existing entry "
            "instead of re-declaring the whole key."
        )
    print("[duplicate check] OK — no duplicate keys across MODERN_TECH_SKILLS or any BATCH_*_ADDITIONS block.")


def _check_no_alias_collisions(taxonomy: dict) -> None:
    alias_owners = {}
    for canonical, entry in taxonomy.items():
        for alias in entry.get("aliases", []):
            alias_owners.setdefault(alias.lower(), []).append(canonical)
        alias_owners.setdefault(canonical.lower(), []).append(canonical)

    collisions = {a: owners for a, owners in alias_owners.items() if len(set(owners)) > 1}
    if collisions:
        print(f"\n⚠️  ALIAS COLLISIONS FOUND ({len(collisions)}) — "
              "each of these phrases is claimed by more than one skill, "
              "only one will actually be reachable:")
        for alias, owners in collisions.items():
            print(f"   {alias!r} claimed by: {sorted(set(owners))}")


def build_taxonomy(onet_path: str, output_path: str) -> None:
    _check_no_duplicate_keys(__file__)

    taxonomy = {}

    print(f"[1/3] Reading O*NET file: {onet_path}")
    onet_count = 0
    hot_count  = 0

    with open(onet_path, "r", encoding="utf-8") as f:
        header = f.readline()
        for line in f:
            parts = line.strip().split("\t")
            if len(parts) < 6:
                continue

            skill_name   = parts[1].strip()
            element_name = parts[3].strip()
            is_hot       = parts[4].strip().upper() == "Y"

            category = ONET_CATEGORY_MAP.get(element_name)
            if category is None and not is_hot:
                continue

            if should_skip(skill_name):
                continue

            if category is None:
                category = "dev_tool"

            source = "onet_hot" if is_hot else "onet"
            aliases = generate_aliases(skill_name)

            if skill_name not in taxonomy:
                taxonomy[skill_name] = {
                    "aliases":  aliases,
                    "category": category,
                    "source":   source,
                }
                onet_count += 1
                if is_hot:
                    hot_count += 1

    print(f"    → Imported {onet_count} skills from O*NET ({hot_count} Hot Technology)")

    print("[2/3] Merging modern tech skills (AWS, RAG, BERT, etc.)")
    custom_count = 0
    dropped_generic_aliases = []

    for canonical, (raw_aliases, category) in MODERN_TECH_SKILLS.items():
        safe_aliases = []
        for a in raw_aliases:
            if _is_too_generic_custom_alias(a):
                dropped_generic_aliases.append((canonical, a))
            else:
                safe_aliases.append(a)
        aliases = safe_aliases

        if canonical in taxonomy:
            existing_aliases = set(taxonomy[canonical]["aliases"])
            existing_aliases.update(aliases)
            existing_aliases.update(generate_aliases(canonical))
            taxonomy[canonical]["aliases"] = sorted(existing_aliases)
            taxonomy[canonical]["category"] = category
            if taxonomy[canonical]["source"] == "onet":
                taxonomy[canonical]["source"] = "onet+custom"
        else:
            all_aliases = sorted(set(aliases) | set(generate_aliases(canonical)))
            taxonomy[canonical] = {
                "aliases":  all_aliases,
                "category": category,
                "source":   "custom",
            }
            custom_count += 1

    print(f"    → Added {custom_count} new custom skills")
    if dropped_generic_aliases:
        print(f"    ⚠️  Dropped {len(dropped_generic_aliases)} too-generic custom alias(es):")
        for canonical, alias in dropped_generic_aliases:
            print(f"       {alias!r} (was an alias of {canonical!r})")

    _check_no_alias_collisions(taxonomy)

    print(f"[3/3] Writing taxonomy to: {output_path}")
    Path(output_path).parent.mkdir(parents=True, exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(taxonomy, f, indent=2, ensure_ascii=False)

    total = len(taxonomy)
    print(f"\n✅ Done! Taxonomy contains {total} canonical skills.")
    print(f"   Breakdown:")
    from collections import Counter
    cats = Counter(v["category"] for v in taxonomy.values())
    for cat, count in sorted(cats.items(), key=lambda x: -x[1]):
        print(f"     {cat:<35} {count}")
    print(f"\n   Output: {output_path}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(
        description="Build skills_taxonomy.json from O*NET + custom modern tech skills"
    )
    parser.add_argument("--onet", default="Software_Skills.txt")
    parser.add_argument("--output", default="data/skills_taxonomy.json")
    args = parser.parse_args()
    build_taxonomy(args.onet, args.output)














